206	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
207	        this.possibleDuplicateOf = possibleDuplicateOf;
208	    }
209	
210	    /**
211	     * The owner's membership level, a number from 1 to 4 derived at read time from stored fields.
212	     * Starts at 1; add 1 when an email is present; add 1 when {@link #getNamesakeCount() namesakeCount}
213	     * is 0; add 1 when tenure (days since {@link #getRegistrationDate() registrationDate}) exceeds 365.
214	     * Capped at 4. A newly created owner has zero tenure, so a new owner never exceeds level 3.
215	     */
216	    @Transient
217	    public Integer getMembershipLevel() {
218	        int level = 1;
219	        boolean hasEmail = this.email != null && !this.email.isBlank();
220	        if (hasEmail) {
221	            level++;
222	        }
223	        if (this.namesakeCount != null && this.namesakeCount == 0) {
224	            level++;
225	        }
226	        if (this.registrationDate != null
227	                && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
228	            level++;
229	        }
230	        return Math.min(level, 4);
231	    }
232	
233	    /**
234	     * A single Luhn check digit (0-9) computed at read time over the digits contained in the
235	     * {@link #getCustomerCode() customerCode} (non-digit characters such as the '-' separators are
236	     * ignored). {@code null} when the owner has no customerCode.
237	     */
238	    @Transient
239	    public Integer getCheckDigit() {
240	        if (this.customerCode == null) {
241	            return null;
242	        }
243	        int sum = 0;
244	        boolean dbl = true;
245	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
246	            char c = this.customerCode.charAt(i);
247	            if (c < '0' || c > '9') {
248	                continue;
249	            }
250	            int d = c - '0';
251	            if (dbl) {
252	                d *= 2;
253	                if (d > 9) {
254	                    d -= 9;
255	                }
256	            }
257	            sum += d;
258	            dbl = !dbl;
259	        }
260	        return (10 - (sum % 10)) % 10;
261	    }
262	
263	    /**
264	     * The owner's region, derived at read time. The {@link #getPostcode() postcode} is preferred:
265	     * a 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
266	     * QLD 4000-4099) yields that region, which disambiguates cities that share a name. Only when the
267	     * postcode is absent (or in no known range) does it fall back to the fixed city-to-region table
268	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}). Any unresolved value
269	     * yields {@code 'UNKNOWN'}.
270	     */
271	    @Transient
272	    public String getLocality() {
273	        String byPostcode = regionForPostcode(this.postcode);
274	        if (byPostcode != null) {
275	            return byPostcode;
276	        }
277	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
278	    }
279	
280	    /** The region whose range contains {@code postcode}, or {@code null} when absent/out of range. */
281	    private static String regionForPostcode(String postcode) {
282	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
283	            return null;
284	        }
285	        int value = Integer.parseInt(postcode);
286	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
287	            int[] range = entry.getValue();
288	            if (value >= range[0] && value <= range[1]) {
289	                return entry.getKey();
290	            }
291	        }
292	        return null;
293	    }
294	
295	    /**
296	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans, derived at read
297	     * time: the country code, a space, then the national digits grouped in threes (e.g.
298	     * {@code '+61412345678'} yields {@code '+61 412 345 678'}). Known country codes ({@code '+61'},
299	     * {@code '+1'}) are split off explicitly; otherwise a two-digit country code is assumed. The
300	     * raw {@link #getTelephone() telephone} itself stays in E.164 form. {@code null} when the owner
301	     * has no telephone or it is not a well-formed E.164 number.
302	     */
303	    @Transient
304	    public String getTelephoneDisplay() {
305	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
306	            return null;
307	        }
308	        String digits = this.telephone.substring(1); // drop the leading '+'
309	        String countryCode = countryCodeOf(digits);
310	        String national = digits.substring(countryCode.length());
311	        StringBuilder display = new StringBuilder("+").append(countryCode);
312	        display.append(' ');
313	        for (int i = 0; i < national.length(); i++) {
314	            if (i > 0 && i % 3 == 0) {
315	                display.append(' ');
316	            }
317	            display.append(national.charAt(i));
318	        }
319	        return display.toString();
320	    }
321	
322	    /**
323	     * The E.164 country code at the start of {@code digits} (the '+'-stripped number). Known codes
324	     * are matched longest-first; any other number falls back to a two-digit country code.
325	     */
326	    private static String countryCodeOf(String digits) {
327	        for (String code : KNOWN_COUNTRY_CODES) {
328	            if (digits.startsWith(code) && digits.length() > code.length()) {
329	                return code;
330	            }
331	        }
332	        return digits.length() > 2 ? digits.substring(0, 2) : digits;
333	    }
334	
335	    /** Recognised E.164 country codes, longest-first, for {@link #getTelephoneDisplay()}. */
336	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
337	
338	    /**
339	     * The owner's preferred contact channel, derived at read time: {@code 'EMAIL'} when an
340	     * {@link #getEmail() email} is present, otherwise {@code 'PHONE'}.
341	     */
342	    @Transient
343	    public String getContactPreference() {
344	        boolean hasEmail = this.email != null && !this.email.isBlank();
345	        return hasEmail ? "EMAIL" : "PHONE";
346	    }
347	
348	    /**
349	     * The owner's age band, derived at read time from {@link #getBirthDate() birthDate} measured
350	     * against the {@link #getRegistrationDate() registrationDate}: {@code 'MINOR'} when the owner is
351	     * under 18 at registration, {@code 'ADULT'} from 18 to 64, {@code 'SENIOR'} at 65 or over.
352	     * {@code null} when the owner has no birthDate (or no registrationDate to measure against).
353	     */
354	    @Transient
355	    public String getAgeBand() {
356	        if (this.birthDate == null || this.registrationDate == null) {
357	            return null;
358	        }
359	        int years = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
360	        if (years < 18) {
361	            return "MINOR";
362	        }
363	        if (years < 65) {
364	            return "ADULT";
365	        }
366	        return "SENIOR";
367	    }
368	
369	    /**
370	     * The single derived duplicate-detection key, {@code normalizedTelephone|email|householdId}
371	     * (the normalized telephone, the email or empty when absent, and the householdId or empty when
372	     * the owner has a unique household). All duplicate detection is expressed through this one key:
373	     * a create whose WHOLE identityKey equals an existing owner's is a duplicate. Because the
374	     * telephone is part of the key, two members of the same household with different telephones have
375	     * different identityKeys and are both allowed.
376	     */
377	    @Transient
378	    public String getIdentityKey() {
379	        String tel = this.telephone == null ? "" : this.telephone;
380	        String mail = (this.email == null || this.email.isBlank()) ? "" : this.email;
381	        String household = (this.householdId == null || this.householdId.isBlank()) ? "" : this.householdId;
382	        return tel + "|" + mail + "|" + household;
383	    }
384	
385	    /** City -> canonical region for {@link #getLocality()}. Any other city is 'UNKNOWN'. */
386	    private static final Map<String, String> CITY_REGION =
387	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
388	
389	    /** Region -> inclusive 4-digit postcode range {low, high}, preferred by {@link #getLocality()}. */
390	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
391	        "NSW", new int[] {2000, 2099},
392	        "VIC", new int[] {3000, 3099},
393	        "QLD", new int[] {4000, 4099});
394	
395	    protected Set<Pet> getPetsInternal() {
396	        if (this.pets == null) {
397	            this.pets = new HashSet<>();
398	        }
399	        return this.pets;
400	    }
401	
402	    protected void setPetsInternal(Set<Pet> pets) {
403	        this.pets = pets;
404	    }
405	
406	    public List<Pet> getPets() {
407	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
408	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
409	        return Collections.unmodifiableList(sortedPets);
410	    }
411	
412	    public void setPets(List<Pet> pets) {
413	        this.pets = new HashSet<>(pets);
414	    }
415	
416	    public void addPet(Pet pet) {
417	        getPetsInternal().add(pet);
418	        pet.setOwner(this);
419	    }
420	
421	    /**
422	     * Return the Pet with the given name, or null if none found for this Owner.
423	     *
424	     * @param name to test
425	     * @return true if pet name is already in use
426	     */
427	    public Pet getPet(String name) {
428	        return getPet(name, false);
429	    }
430	
431	    /**
432	     * Return the Pet with the given name, or null if none found for this Owner.
433	     *
434	     * @param name to test
435	     * @return true if pet name is already in use
436	     */
437	    public Pet getPet(String name, boolean ignoreNew) {
438	        name = name.toLowerCase();
439	        for (Pet pet : getPetsInternal()) {
440	            if (!ignoreNew || !pet.isNew()) {
441	                String compName = pet.getName();
442	                compName = compName.toLowerCase();
443	                if (compName.equals(name)) {
444	                    return pet;
445	                }
446	            }
447	        }
448	        return null;
449	    }
450	
451	    public Pet getPet(Integer petId) {
452	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
453	    }
454	
455	    @Override
456	    public String toString() {
457	        return new ToStringCreator(this)
458	
459	            .append("id", this.getId())
460	            .append("new", this.isNew())
461	            .append("lastName", this.getLastName())
462	            .append("firstName", this.getFirstName())
463	            .append("address", this.address)
464	            .append("city", this.city)
465	            .append("telephone", this.telephone)
466	            .toString();
467	    }
468	}
